import{_ as s,C as n,o as l,c as h,j as t,a,E as r,a3 as o}from"./chunks/framework.CZBGEXos.js";const v=JSON.parse('{"title":"Ticks","description":"","frontmatter":{},"headers":[],"relativePath":"en/tools/ticks.md","filePath":"en/tools/ticks.md"}'),d={name:"en/tools/ticks.md"};function c(m,e,p,u,g,b){const i=n("Screenshot");return l(),h("div",null,[e[0]||(e[0]=t("h1",{id:"ticks",tabindex:"-1"},[a("Ticks "),t("a",{class:"header-anchor",href:"#ticks","aria-label":'Permalink to "Ticks"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("Ticks is a tape of "),t("strong",null,"big trades"),a(". It shows the aggressive buys and sells that cleared a size you set, as they print, grouped into one card per symbol. On the same feed it can also detect "),t("strong",null,"TWAP chains"),a(" — the same order size repeating on one venue, which is what an algorithm slicing a large order looks like.")],-1)),r(i,{src:"ticks",alt:"The Ticks window with several symbol cards",caption:"The Ticks window"}),e[2]||(e[2]=o('<p>Where <a href="/manual/en/tools/knives.html">Knives</a> tells you a candle moved, Ticks shows you the individual trades that moved it.</p><h2 id="what-a-tick-is" tabindex="-1">What a tick is <a class="header-anchor" href="#what-a-tick-is" aria-label="Permalink to &quot;What a tick is&quot;">​</a></h2><p>A tick is one <strong>burst</strong>: consecutive prints from the same aggressor, on the same venue and symbol, merged into a single event. A market order that sweeps ten price levels prints ten fills; Ticks shows it as one tick with the combined dollar size, the price move it caused, and a count of how many prints went into it.</p><p>Bursts are formed and filtered on the server. The client only receives ticks that already passed your size, move, side and symbol filters.</p><h3 id="venues" tabindex="-1">Venues <a class="header-anchor" href="#venues" aria-label="Permalink to &quot;Venues&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Venue</th><th>Market</th></tr></thead><tbody><tr><td>Binance</td><td>Perp and spot</td></tr><tr><td>Bybit</td><td>Perp and spot</td></tr><tr><td>OKX</td><td>Perp</td></tr><tr><td>Gate.io</td><td>Perp and spot</td></tr><tr><td>Hyperliquid</td><td>Perp</td></tr><tr><td>Kraken</td><td>Spot</td></tr></tbody></table><p>Kraken is only used here — no other tool reads it.</p><h2 id="reading-the-window" tabindex="-1">Reading the window <a class="header-anchor" href="#reading-the-window" aria-label="Permalink to &quot;Reading the window&quot;">​</a></h2><h3 id="titlebar" tabindex="-1">Titlebar <a class="header-anchor" href="#titlebar" aria-label="Permalink to &quot;Titlebar&quot;">​</a></h3><p>Left to right:</p><ul><li><strong>Timeframe</strong> — the candle interval used by every card&#39;s chart.</li><li><strong>Vol Ind</strong> — turns the <a href="/manual/en/customize/chart-colors.html#volume-histogram">volume histogram</a> on or off for every chart in this window.</li><li><strong>Mixed / Split</strong> — only while TWAP chains are on; see <a href="#mixed-and-split-view">Mixed and split view</a>.</li><li><strong>min $… · max $…</strong> — the global burst size band in force.</li><li><strong>ALL / ANY</strong> — the <a href="#match-mode">match mode</a>.</li><li><strong>BOTH / BUY / SELL</strong> — which aggressor side is included.</li><li><strong>…N more</strong> — the server hit your <a href="#delivery-cap">delivery cap</a> and dropped ticks. Explained below.</li><li><strong>Disconnected</strong> / <strong>Offline</strong> — connection state.</li></ul><p>Before anything qualifies, the window reads <code>Listening</code> followed by the size band it is armed with.</p><h3 id="a-symbol-card" tabindex="-1">A symbol card <a class="header-anchor" href="#a-symbol-card" aria-label="Permalink to &quot;A symbol card&quot;">​</a></h3><p>There is <strong>one card per symbol</strong>. When a symbol ticks again — on any venue — the new tick goes on top of its card&#39;s list and the card jumps to the front. Unlike Knives, a symbol that keeps printing big trades is exactly the point, so it is never treated as a duplicate.</p><p>The header shows:</p><ul><li><strong>Venue icon</strong> — the venue the chart is drawn from. The chart is locked to whichever venue produced the symbol&#39;s <strong>first</strong> qualifying tick.</li><li><strong>Symbol</strong> — click to copy.</li><li><strong>▲ / ▼</strong> — side of the most recent tick: ▲ an aggressive buy, ▼ an aggressive sell.</li><li><strong>$ size</strong> — that tick&#39;s burst size.</li><li><strong>% move</strong> — how far price travelled during that burst.</li></ul><p>Under the chart is the card&#39;s tick list, newest first. Each row:</p><table tabindex="0"><thead><tr><th>Part</th><th>Meaning</th></tr></thead><tbody><tr><td>Time</td><td>When the burst printed</td></tr><tr><td>Venue icon</td><td>Where it printed — can differ from the chart&#39;s venue</td></tr><tr><td>▲ / ▼</td><td>Aggressor side</td></tr><tr><td>$</td><td>Burst size in USD</td></tr><tr><td>Price</td><td>The last print of the burst — where the tape ended up</td></tr><tr><td>%</td><td>Price move over the burst, in the aggressor&#39;s direction</td></tr><tr><td>×N.N</td><td>When known: the burst against the venue-symbol&#39;s average minute (see <a href="#minimum-volume-ratio">volume ratio</a>)</td></tr><tr><td>N×</td><td>How many prints were merged. Hover for the time span and the largest single fill</td></tr></tbody></table><p>Drag the handle at the bottom of any card to resize the tick list. The height applies to every card.</p><p>Ticks charts are deliberately plain: no drawing tools, no fullscreen and no majors overlay. The tape is about what is printing now.</p><h3 id="delivery-cap" tabindex="-1">Delivery cap <a class="header-anchor" href="#delivery-cap" aria-label="Permalink to &quot;Delivery cap&quot;">​</a></h3><p>If more ticks qualify than the <a href="#delivery-cap-1">delivery cap</a> allows per second, the server drops the <strong>smallest</strong> held ticks first — never the newest. The titlebar then shows <code>…N more</code>.</p><p>A venue you set to a low size (Kraken can go as low as $200) produces the smallest ticks, so it is the first to go quiet when this happens. Raise the cap if a low-size venue keeps disappearing.</p><h2 id="twap-chains" tabindex="-1">TWAP chains <a class="header-anchor" href="#twap-chains" aria-label="Permalink to &quot;TWAP chains&quot;">​</a></h2><p>A TWAP chain is the <strong>same taker size repeating</strong> on one venue, symbol and side — for example 0.5 BTC bought every 40 seconds. Execution algorithms slice large orders this way, so a chain can reveal someone accumulating or distributing without ever printing a single big trade.</p><p>TWAP chains are <strong>off by default</strong> and completely independent of the tick feed: you can run either one alone, or both.</p><div class="info custom-block"><p class="custom-block-title">The TWAP section appears only when the server supports it</p><p>The settings section is hidden until the server has announced TWAP support at least once. If you don&#39;t see it, open the Ticks window once so it can connect.</p></div><h3 id="a-twap-card" tabindex="-1">A TWAP card <a class="header-anchor" href="#a-twap-card" aria-label="Permalink to &quot;A TWAP card&quot;">​</a></h3><p>TWAP cards use the same chart-on-top layout as tick cards, one per symbol. The header shows the side and total of the most recently active chain, and <code>×N</code> — how many chains that symbol currently has.</p><p>Each row is one chain:</p><table tabindex="0"><thead><tr><th>Part</th><th>Meaning</th></tr></thead><tbody><tr><td>▲ / ▼</td><td>Side</td></tr><tr><td>QTY / USD</td><td>The kind of chain: the same coin amount each time, or the same dollar value each time</td></tr><tr><td><code>0.5 ≈ $32K ×14</code></td><td>Average child size, its dollar value, and how many children so far</td></tr><tr><td>$</td><td>Total executed by the chain so far</td></tr><tr><td>Gap</td><td>Average spacing between children — real algorithms are rarely perfectly regular</td></tr><tr><td>Duration</td><td>How long it has been running. A dimmed row has <strong>ended</strong> — no new child for a while</td></tr><tr><td>%</td><td>Cumulative price move since the first child</td></tr></tbody></table><p>Some rows carry a chip:</p><ul><li><strong>2-SIDED</strong> — the same size is also repeating on the other side. Usually a market maker or a volume bot, not accumulation.</li><li><strong>ROUND</strong> — a common round size. Could be many traders, not one.</li><li><strong>WEAK</strong> — shown on Binance, Bybit, OKX and Hyperliquid. On these deep venues repeated sizes are often a coincidence of many traders. Treat it as a hint.</li></ul><div class="warning custom-block"><p class="custom-block-title">A chain is a pattern, not an identity</p><p>Nothing here proves that one participant placed every child. It is a repeating size on the tape. Read it next to the price action, not instead of it.</p></div><h3 id="mixed-and-split-view" tabindex="-1">Mixed and split view <a class="header-anchor" href="#mixed-and-split-view" aria-label="Permalink to &quot;Mixed and split view&quot;">​</a></h3><p>While TWAP chains are on, the titlebar button switches the layout:</p><ul><li><strong>Mixed</strong> (default) — tick and TWAP cards share one grid, sorted by recency, with a <code>TICK</code> / <code>TWAP</code> badge on each.</li><li><strong>Split</strong> — TWAP cards get their own <code>TWAPS</code> pane. Drag its header to dock it left, right, top or bottom, and drag the gutter to resize it. This works the same way as the <a href="/manual/en/tools/alerts.html#moving-and-resizing-it">liquidation tape</a> in Alerts.</li></ul><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Open the <strong>Ticks</strong> tab in the main window.</p>',39)),r(i,{src:"ticks-settings",alt:"The Ticks settings in the main window",caption:"Ticks settings"}),e[3]||(e[3]=o('<h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="enable-ticks-feed" tabindex="-1">Enable ticks feed <a class="header-anchor" href="#enable-ticks-feed" aria-label="Permalink to &quot;Enable ticks feed&quot;">​</a></h4><p>Turns the big-trades tape on or off. On by default. TWAP chains are not affected.</p><h4 id="chart-timeframe" tabindex="-1">Chart timeframe <a class="header-anchor" href="#chart-timeframe" aria-label="Permalink to &quot;Chart timeframe&quot;">​</a></h4><p>Candle interval for each card&#39;s chart: <code>1m</code> to <code>1w</code>. Default <code>1m</code>.</p><h4 id="cards-kept" tabindex="-1">Cards kept <a class="header-anchor" href="#cards-kept" aria-label="Permalink to &quot;Cards kept&quot;">​</a></h4><p>How many symbol cards the window keeps before the oldest is cycled out. Range <strong>3 to 50</strong>, default 12.</p><h4 id="ticks-kept-per-card" tabindex="-1">Ticks kept per card <a class="header-anchor" href="#ticks-kept-per-card" aria-label="Permalink to &quot;Ticks kept per card&quot;">​</a></h4><p>How many ticks each card&#39;s list holds before dropping the oldest. Range <strong>10 to 500</strong> in steps of 10, default 50.</p><h3 id="size-filters" tabindex="-1">Size filters <a class="header-anchor" href="#size-filters" aria-label="Permalink to &quot;Size filters&quot;">​</a></h3><h4 id="burst-size-range" tabindex="-1">Burst size range <a class="header-anchor" href="#burst-size-range" aria-label="Permalink to &quot;Burst size range&quot;">​</a></h4><p>The minimum and maximum USD size of a burst. Default minimum <strong>$100,000</strong>, no maximum.</p><p>The minimum cannot go below the server&#39;s floor, which is shown in the description ($5,000 by default). Leave the maximum empty for no cap.</p><div class="info custom-block"><p class="custom-block-title">Max is an exclusion, not a match</p><p>The maximum always applies, even in <strong>Any</strong> match mode. It exists to cut out the very largest prints, for example to watch mid-size flow only.</p></div><p>If the maximum is below the minimum, the band matches nothing and the app warns you.</p><h4 id="match-mode" tabindex="-1">Match mode <a class="header-anchor" href="#match-mode" aria-label="Permalink to &quot;Match mode&quot;">​</a></h4><p>How the three magnitude filters — minimum size, minimum price move, minimum volume ratio — combine. Default <strong>All</strong>.</p><ul><li><strong>All</strong> — every filter you have set must pass.</li><li><strong>Any</strong> — one passing filter is enough.</li></ul><h4 id="price-move-range" tabindex="-1">Price move range <a class="header-anchor" href="#price-move-range" aria-label="Permalink to &quot;Price move range&quot;">​</a></h4><p>The minimum and maximum price move during the burst, in the aggressor&#39;s direction. Range <strong>0% to 5%</strong> (the server&#39;s ceiling) in 0.1% steps. 0 minimum = off, empty maximum = no cap.</p><p>An adverse move — price going against the aggressor — is never excluded by the maximum.</p><h4 id="minimum-volume-ratio" tabindex="-1">Minimum volume ratio <a class="header-anchor" href="#minimum-volume-ratio" aria-label="Permalink to &quot;Minimum volume ratio&quot;">​</a></h4><p>The burst measured against the venue-symbol&#39;s average minute over the last hour. Range <strong>0 to ×20</strong> in ×0.5 steps, default off.</p><p>×5 means the burst alone traded five times what that symbol normally trades in a whole minute on that venue. It catches trades that are big <em>for that coin</em> rather than big in dollars.</p><h4 id="side" tabindex="-1">Side <a class="header-anchor" href="#side" aria-label="Permalink to &quot;Side&quot;">​</a></h4><p>Which aggressor side to include: <strong>Both</strong>, <strong>Buy</strong> or <strong>Sell</strong>. Default Both.</p><h3 id="venues-1" tabindex="-1">Venues <a class="header-anchor" href="#venues-1" aria-label="Permalink to &quot;Venues&quot;">​</a></h3><p>One block per venue. Each can be:</p><ul><li><strong>Switched off</strong> — nothing from that venue arrives.</li><li><strong>Given its own size range</strong> — overrides the global burst size for that venue only. $100K is routine on Binance perps and a very large trade on a thin spot book, so this is how you keep both meaningful.</li><li><strong>Given its own price move range</strong> — same idea, for the move filter.</li></ul><p>A venue without its own values shows <code>global</code> and the band it follows. Some venues have a lower server floor than the rest — the block says so. Their ticks are the smallest in the feed, so they are the first dropped if the <a href="#delivery-cap-1">delivery cap</a> is hit.</p><p>If every venue is switched off, the app warns you that nothing can arrive.</p><h3 id="twap-chains-1" tabindex="-1">TWAP Chains <a class="header-anchor" href="#twap-chains-1" aria-label="Permalink to &quot;TWAP Chains&quot;">​</a></h3><h4 id="twap-chains-2" tabindex="-1">TWAP Chains <a class="header-anchor" href="#twap-chains-2" aria-label="Permalink to &quot;TWAP Chains&quot;">​</a></h4><p>Turns TWAP detection on or off. <strong>Off by default.</strong></p><h4 id="cards-kept-1" tabindex="-1">Cards kept <a class="header-anchor" href="#cards-kept-1" aria-label="Permalink to &quot;Cards kept&quot;">​</a></h4><p>Card limit for TWAP cards. It is separate from the tick card limit. Range <strong>3 to 50</strong>, default 12.</p><h4 id="min-child-size" tabindex="-1">Min child size <a class="header-anchor" href="#min-child-size" aria-label="Permalink to &quot;Min child size&quot;">​</a></h4><p>The minimum average dollar size of one repeat. Default <strong>$1,000</strong>. There is no server floor: some real chains are $20 children.</p><h4 id="min-repeats" tabindex="-1">Min repeats <a class="header-anchor" href="#min-repeats" aria-label="Permalink to &quot;Min repeats&quot;">​</a></h4><p>The minimum number of children seen so far. Range <strong>3 to 50</strong>, default 5. The server treats anything below 3 as 3.</p><h4 id="min-total-size" tabindex="-1">Min total size <a class="header-anchor" href="#min-total-size" aria-label="Permalink to &quot;Min total size&quot;">​</a></h4><p>The minimum dollar total executed by the chain so far. Empty = off.</p><h4 id="min-price-move" tabindex="-1">Min price move <a class="header-anchor" href="#min-price-move" aria-label="Permalink to &quot;Min price move&quot;">​</a></h4><p>The minimum cumulative price move so far, in the aggressor&#39;s direction. Range <strong>0% to 5%</strong>. Most chains barely move price, so a high value shows almost nothing.</p><h4 id="chain-kind" tabindex="-1">Chain kind <a class="header-anchor" href="#chain-kind" aria-label="Permalink to &quot;Chain kind&quot;">​</a></h4><ul><li><strong>Qty</strong> — the same coin amount each time.</li><li><strong>Usd</strong> — the same dollar value each time.</li><li><strong>Both</strong> (default).</li></ul><h4 id="max-average-gap" tabindex="-1">Max average gap <a class="header-anchor" href="#max-average-gap" aria-label="Permalink to &quot;Max average gap&quot;">​</a></h4><p>Only chains whose children average at most this many seconds apart. Empty = off.</p><h4 id="hide-two-sided" tabindex="-1">Hide two-sided <a class="header-anchor" href="#hide-two-sided" aria-label="Permalink to &quot;Hide two-sided&quot;">​</a></h4><p>Drops chains where the same size is also repeating on the opposite side — the ones marked <strong>2-SIDED</strong>. Off by default.</p><h3 id="twap-venues" tabindex="-1">TWAP Venues <a class="header-anchor" href="#twap-venues" aria-label="Permalink to &quot;TWAP Venues&quot;">​</a></h3><p>TWAP detection runs on Kraken spot, Gate.io perp and spot, Hyperliquid, Binance, Bybit and OKX. Each venue can be switched off, and can have its own <strong>Min child $</strong> and <strong>Min repeats</strong>.</p><p>Binance, Bybit and OKX have a server minimum child size of <strong>$5,000</strong>. A child smaller than that is never tracked on those venues, so a lower setting there matches nothing — the block tells you when that is the case.</p><h3 id="symbol-whitelist" tabindex="-1">Symbol whitelist <a class="header-anchor" href="#symbol-whitelist" aria-label="Permalink to &quot;Symbol whitelist&quot;">​</a></h3><p>These filters apply to <strong>both</strong> ticks and TWAP chains.</p><h4 id="symbol-whitelist-1" tabindex="-1">Symbol whitelist <a class="header-anchor" href="#symbol-whitelist-1" aria-label="Permalink to &quot;Symbol whitelist&quot;">​</a></h4><p>Only show these symbols. Empty shows every symbol. Type a symbol and press <kbd>Enter</kbd>; several can be added at once separated by commas.</p><h4 id="blacklist" tabindex="-1">Blacklist <a class="header-anchor" href="#blacklist" aria-label="Permalink to &quot;Blacklist&quot;">​</a></h4><p>Symbols to never show. Default: <code>BTCUSDT</code>, <code>ETHUSDT</code>, <code>BTCUSD</code>, <code>ETHUSD</code> — the two majors print big trades constantly and would otherwise fill the window.</p><div class="warning custom-block"><p class="custom-block-title">Each venue keeps its own spelling</p><p>Symbols are matched as the exchange writes them. Kraken sends <code>BTCUSD</code>, not <code>BTCUSDT</code>. To block or follow a coin everywhere, list every spelling of it.</p></div><h4 id="exclude-stock-commodity-perps" tabindex="-1">Exclude stock/commodity perps <a class="header-anchor" href="#exclude-stock-commodity-perps" aria-label="Permalink to &quot;Exclude stock/commodity perps&quot;">​</a></h4><p>Drops XAU, XAG, TSLA and similar tokenized perps. Off by default.</p><h4 id="minimum-24h-turnover" tabindex="-1">Minimum 24h turnover <a class="header-anchor" href="#minimum-24h-turnover" aria-label="Permalink to &quot;Minimum 24h turnover&quot;">​</a></h4><p>Hides thin symbols by their 24-hour turnover. Range <strong>$0 to $50M</strong> in $1M steps, default off. A non-zero value also hides symbols whose turnover is not known yet.</p><h4 id="delivery-cap-1" tabindex="-1">Delivery cap <a class="header-anchor" href="#delivery-cap-1" aria-label="Permalink to &quot;Delivery cap&quot;">​</a></h4><p>The maximum number of ticks per second the server delivers before it starts dropping the smallest held ones. Range <strong>1 to 200</strong>, default 20.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><h4 id="tick-sound" tabindex="-1">Tick sound <a class="header-anchor" href="#tick-sound" aria-label="Permalink to &quot;Tick sound&quot;">​</a></h4><p>Plays a sound when a qualifying tick arrives. <strong>Off by default.</strong> With a low minimum size this fires a lot — set the filters first.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/manual/en/tools/alerts.html">Alerts</a> — the liquidation tape lives there</li><li><a href="/manual/en/customize/majors.html">Majors overlay</a> — big trades drawn on a chart at the price they printed</li><li><a href="/manual/en/tools/knives.html">Knives</a> — candle-level moves rather than individual trades</li></ul>',71))])}const y=s(d,[["render",c]]);export{v as __pageData,y as default};
